/*
 * A295021  Cubes whose largest digit is 6.
 * https://oeis.org/A295021
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 6, u32 n <= 31, u64 n <= 31, u128 n <= 31,
 *            big any n
 * Validated: partial, pass, 31 terms through n = 31 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: a(n) = n-th cube whose largest decimal digit is 6 */
/* The sequence is generated by brute‑force enumeration of consecutive cubes. */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/mem.h"

/* Return true iff all decimal digits of x are ≤ 6 and at least one digit is 6. */
static bool cube_ok(seq_t x)
{
    bool has6 = false;
    while (x > 0)
    {
        unsigned d = (unsigned)(x % 10);
        if (d > 6) return false;
        if (d == 6) has6 = true;
        x /= 10;
    }
    return has6;
}

seq_t a(idx_t n)
{
    static seq_t *table = NULL;   /* table[i] holds a(i+1) */
    static size_t len   = 0;      /* number of terms stored so far   */
    static size_t cap   = 0;      /* allocated capacity               */
    static idx_t  next_m = 1;     /* next integer to test (1‑based)   */

    while (len < n)
    {
        seq_t m = (seq_t)next_m;
        seq_t cube = m * m;
        cube *= m;                     /* compute m³ */

        if (cube_ok(cube))
        {
            if (len + 1 > cap)
            {
                size_t new_cap = (cap == 0) ? 16 : (cap << 1);
                void *p = mem_resize(seq_t, table, new_cap);
                if (!p) abort();
                table = (seq_t*)p;
                cap   = new_cap;
            }
            table[len++] = cube;
        }
        ++next_m;
    }
    return table[n - 1];
}
